//! Resumable knowledge-representation workflow fabrics for Worldgen P04 F13-F16.
use std::collections::BTreeSet;
use super::knowledge_copilot_support::{self, KnowledgeCopilotRequest, KnowledgeCopilotReceipt};
use super::knowledge_representation_support::KnowledgeRepresentationRequest;
use bioprism_foundation::{PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;

pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.knowledge-workflow-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct KnowledgeWorkflowRequest{pub workflow_id:String,pub copilot:KnowledgeCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct KnowledgeWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:KnowledgeCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum KnowledgeWorkflowError{#[error("invalid knowledge workflow request: {0}")]Invalid(String),#[error("invalid knowledge workflow receipt: {0}")]Receipt(String),#[error("knowledge workflow artifact failed: {0}")]Artifact(String)}
fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn sorted(v:&[String])->Vec<String>{let mut out=v.to_vec();out.sort();out.dedup();out}
impl KnowledgeWorkflowReceipt{pub fn validate(&self)->Result<(),KnowledgeWorkflowError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.stage_order.len()!=self.completed_stage_order.len()+self.pending_stage_order.len()||self.checkpoint_seq==0||self.budget_units==0||self.consumed_units>self.budget_units||self.effect_receipts.is_empty()||![&self.replay_identity,&self.workflow_digest].into_iter().all(digest){return Err(KnowledgeWorkflowError::Receipt("knowledge workflow identity, stages, budget, locality, digests, or effects are incomplete".into()));}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !ordered(v){return Err(KnowledgeWorkflowError::Receipt("knowledge workflow ordering is not canonical".into()));}}let ids=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<Vec<_>>();if ids.len()!=self.stage_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids{return Err(KnowledgeWorkflowError::Receipt("knowledge workflow stages do not partition".into()));}if self.copilot.validate().is_err(){return Err(KnowledgeWorkflowError::Receipt("nested knowledge copilot receipt is invalid".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(KnowledgeWorkflowError::Receipt("knowledge workflow artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("schedule:worldgen-knowledge-workflow:")){return Err(KnowledgeWorkflowError::Receipt("knowledge workflow effect is outside scheduling gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["knowledge engineer","graph compiler","workflow operator","downstream graph consumer"],"behavior":format!("orchestrate resumable typed knowledge representation for {scale}"),"value":"makes graph construction restartable, budgeted, compensating, and replayable without hidden effects","input_schema":input_schema,"output_schema":"KnowledgeWorkflowReceipt1@1","effects":["schedule:worldgen-knowledge-workflow","block:unsafe-release"],"permissions":["schedule:bounded-knowledge-workflow"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn schedule(request:&KnowledgeWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<KnowledgeWorkflowReceipt,KnowledgeWorkflowError>{if request.workflow_id.trim().is_empty()||request.stage_order.is_empty()||request.budget_units==0||request.checkpoint_seq==0||!request.compensation_enabled||!digest(&request.replay_identity)||request.copilot.knowledge_request.replay_identity!=request.replay_identity{return Err(KnowledgeWorkflowError::Invalid("knowledge workflow identity, stages, checkpoint, budget, compensation, or replay is invalid".into()));}let stages=sorted(&request.stage_order);if stages.len()!=request.stage_order.len()||request.completed_stage_order.iter().any(|stage|!stages.contains(stage)){return Err(KnowledgeWorkflowError::Invalid("knowledge workflow stages must be unique and declared".into()));}let copilot=knowledge_copilot_support::run(&request.copilot,feature_id,version,scale,require_approval,require_federation).map_err(|error|KnowledgeWorkflowError::Invalid(error.to_string()))?;let completed=request.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();let pending=stages.iter().filter(|stage|!completed.contains(*stage)).cloned().collect::<Vec<_>>();let consumed=(request.copilot.action_order.len() as u64).min(request.budget_units);let mut compensation=Vec::new();if copilot.disposition=="blocked"||request.copilot.action_order.len() as u64>request.budget_units{compensation.push(format!("workflow:{}:retain-partial-knowledge-graph",request.workflow_id));}let disposition=if copilot.disposition=="blocked"||!compensation.is_empty(){"blocked"}else if pending.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="qualified"{vec![format!("schedule:worldgen-knowledge-workflow:{}",request.workflow_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"workflow_id":request.workflow_id,"disposition":disposition,"stage_order":stages,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":compensation,"checkpoint_seq":request.checkpoint_seq,"budget_units":request.budget_units,"consumed_units":consumed,"replay_identity":request.replay_identity,"copilot":copilot.clone(),"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let workflow_digest=ContentHash::of_value(&payload).map_err(|error|KnowledgeWorkflowError::Artifact(error.to_string()))?;let compensation_order=sorted(&payload["compensation_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>());let receipt=KnowledgeWorkflowReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:request.workflow_id.clone(),disposition:disposition.into(),stage_order:sorted(&request.stage_order),completed_stage_order:sorted(&request.completed_stage_order),pending_stage_order:pending,compensation_order,checkpoint_seq:request.checkpoint_seq,budget_units:request.budget_units,consumed_units:consumed,replay_identity:request.replay_identity.clone(),copilot,workflow_digest:workflow_digest.clone(),artifact:json!({"artifact_id":format!("worldgen-knowledge-workflow:{}",request.workflow_id),"content_type":CONTENT_TYPE,"content_hash":workflow_digest,"boundary":PRECLINICAL_BOUNDARY}),effect_receipts:sorted(&effects),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
#[cfg(test)]mod tests{use super::*;use crate::knowledge_copilot_support::KnowledgeCopilotRequest;use crate::knowledge_representation_support::{KnowledgeNode,KnowledgeRelation};fn hash(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn request()->KnowledgeWorkflowRequest{let replay=hash("replay");let node=KnowledgeNode{node_id:"node:a".into(),semantic_type:"gene".into(),label:"A".into(),confidence_milli:900,state:bioprism_foundation::EvidenceState::Supported,evidence_digest:hash("e"),provenance_digest:hash("p"),artifact_digest:hash("a"),replay_identity:replay.clone(),negative_result:false,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};let relation=KnowledgeRelation{relation_id:"rel:a".into(),subject_id:"node:a".into(),predicate:"associated-with".into(),object_id:"node:a".into(),evidence_digest:hash("re"),provenance_digest:hash("rp"),replay_identity:replay.clone(),raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};let knowledge=KnowledgeRepresentationRequest{request_id:"workflow:req".into(),namespace:"preclinical".into(),required_node_order:vec!["node:a".into()],required_relation_order:vec!["rel:a".into()],minimum_confidence_milli:500,nodes:vec![node],relations:vec![relation],replay_identity:replay.clone(),policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};KnowledgeWorkflowRequest{workflow_id:"workflow:knowledge".into(),copilot:KnowledgeCopilotRequest{knowledge_request:knowledge,action_order:vec!["read:graph".into()],action_budget:2,dry_run:false,signed_approval:true,federation_approved:true,boundary:PRECLINICAL_BOUNDARY.into()},stage_order:vec!["represent".into(),"audit".into()],completed_stage_order:vec!["audit".into(),"represent".into()],checkpoint_seq:1,budget_units:4,compensation_enabled:true,replay_identity:replay}}#[test]fn completed_knowledge_workflow_schedules(){let r=schedule(&request(),"AFA-worldgen-P04-F13","worldgen-local-knowledge-workflow/1.0","local single-study",false,false).unwrap();assert_eq!(r.disposition,"qualified");assert!(r.digest().is_ok());}#[test]fn pending_stage_is_partial(){let mut q=request();q.completed_stage_order=vec!["represent".into()];let r=schedule(&q,"AFA-worldgen-P04-F14","worldgen-multimodal-knowledge-workflow/1.0","multimodal multi-study",true,false).unwrap();assert_eq!(r.disposition,"partial");}}
impl KnowledgeWorkflowReceipt{pub fn digest(&self)->Result<ContentHash,KnowledgeWorkflowError>{self.validate()?;let value=serde_json::to_value(self).map_err(|e|KnowledgeWorkflowError::Artifact(e.to_string()))?;ContentHash::of_value(&value).map_err(|e|KnowledgeWorkflowError::Artifact(e.to_string()))}}
